      integer  :: g0, g1, g2, g3
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:)
      real(dp) :: s(0:8)

      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g1 = g0 + envs%g_stride_i
      g2 = g0 + envs%g_stride_i
      g3 = g1 + envs%g_stride_i
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g3p(ix+0)*g0p(iy+0)*g0p(iz+0)
         s(1) = + g2p(ix+0)*g1p(iy+0)*g0p(iz+0)
         s(2) = + g2p(ix+0)*g0p(iy+0)*g1p(iz+0)
         s(3) = + g1p(ix+0)*g2p(iy+0)*g0p(iz+0)
         s(4) = + g0p(ix+0)*g3p(iy+0)*g0p(iz+0)
         s(5) = + g0p(ix+0)*g2p(iy+0)*g1p(iz+0)
         s(6) = + g1p(ix+0)*g0p(iy+0)*g2p(iz+0)
         s(7) = + g0p(ix+0)*g1p(iy+0)*g2p(iz+0)
         s(8) = + g0p(ix+0)*g0p(iy+0)*g3p(iz+0)
         if (gout_empty /= 0) then
            gout(n*1+0) = + s(0) + s(4) + s(8)
         else
            gout(n*1+0) = gout(n*1+0) + ( + s(0) + s(4) + s(8) )
         end if
      end do
   end subroutine CINTgout1e_int1e_r2_origi

