      g11 = g3 + envs%g_stride_k
      g12 = g4 + envs%g_stride_k
      g13 = g5 + envs%g_stride_k
      g14 = g6 + envs%g_stride_k
      g15 = g7 + envs%g_stride_k
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)
      g4p(0:) => g(g4:)
      g5p(0:) => g(g5:)
      g6p(0:) => g(g6:)
      g7p(0:) => g(g7:)
      g8p(0:) => g(g8:)
