      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:)
      real(dp) :: s(0:26)

      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
